import{_ as o,o as e,c as r,a2 as l}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"퀵 패널 설정","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 핵심 아키텍처 및 메인 스위치","slug":"_1-핵심-아키텍처-및-메인-스위치","link":"#_1-핵심-아키텍처-및-메인-스위치","children":[]},{"level":2,"title":"2. 워크스페이스 (Workspaces)","slug":"_2-워크스페이스-workspaces","link":"#_2-워크스페이스-workspaces","children":[]},{"level":2,"title":"3. 소스 설정 (Sources)","slug":"_3-소스-설정-sources","link":"#_3-소스-설정-sources","children":[]},{"level":2,"title":"4. 플러그인 동적 탭 (Plugin Tabs)","slug":"_4-플러그인-동적-탭-plugin-tabs","link":"#_4-플러그인-동적-탭-plugin-tabs","children":[]},{"level":2,"title":"5. 앱 연동 및 전용 블랙리스트","slug":"_5-앱-연동-및-전용-블랙리스트","link":"#_5-앱-연동-및-전용-블랙리스트","children":[]},{"level":2,"title":"6. 패널 조작 가이드","slug":"_6-패널-조작-가이드","link":"#_6-패널-조작-가이드","children":[]}],"relativePath":"ko-KR/user-guide/settings/quick-panel.md","filePath":"ko-KR/user-guide/settings/quick-panel.md","lastUpdated":1791112464000}'),s={name:"ko-KR/user-guide/settings/quick-panel.md"};function n(i,t,g,a,d,c){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="퀵-패널-설정" tabindex="-1">퀵 패널 설정 <a class="header-anchor" href="#퀵-패널-설정" aria-label="Permalink to &quot;퀵 패널 설정&quot;">​</a></h1><p><strong>퀵 패널 (Quick Panel)</strong> 은 자주 사용하는 파일의 빠른 호출, 프로젝트 컨텍스트 관리 및 데스크톱 드래그 앤 드롭 파일 스테이징을 위해 설계된 플로팅 워크스페이스입니다. 단축키를 누르면 활성 창의 우측 하단에 자동 도킹되어 작업 중인 컨텍스트를 벗어나지 않고 파일을 빠르게 탐색하고 활용할 수 있습니다.</p><h2 id="_1-핵심-아키텍처-및-메인-스위치" tabindex="-1">1. 핵심 아키텍처 및 메인 스위치 <a class="header-anchor" href="#_1-핵심-아키텍처-및-메인-스위치" aria-label="Permalink to &quot;1. 핵심 아키텍처 및 메인 스위치&quot;">​</a></h2><ul><li><strong>퀵 패널 활성화</strong>: 전체 켜기/끄기 스위치로, 끄면 호출 단축키가 작동하지 않습니다.</li><li><strong>호출 단축키</strong>: 기본값 <strong><code>Ctrl+F2</code></strong>(<a href="./hotkeys-page.html"><strong>설정 → 단축키</strong></a>에서 변경 가능).</li><li><strong>스마트 도킹 및 크기 제한</strong>: 호스트 창의 너비 및 높이의 각 1/2 크기로 표시됩니다(시인성을 위해 최소 <code>280 × 200px</code>로 제한). Lertaro 자체 창이 활성 상태일 때는 중복 실행 방지를 위해 호출이 무시되며, 패널이 열려 있을 때 동일한 단축키를 누르면 닫힙니다.</li></ul><h2 id="_2-워크스페이스-workspaces" tabindex="-1">2. 워크스페이스 (Workspaces) <a class="header-anchor" href="#_2-워크스페이스-workspaces" aria-label="Permalink to &quot;2. 워크스페이스 (Workspaces)&quot;">​</a></h2><p>프로젝트나 업무 단위로 폴더 그룹을 구성합니다.</p><ul><li><strong>워크스페이스 관리</strong>: 좌측 목록에서 <strong>새로 만들기</strong>, <strong>복제</strong>, <strong>삭제</strong>가 가능하며 드래그하여 탭 바의 표시 순서를 변경할 수 있습니다.</li><li><strong>속성</strong>: <ul><li><strong>이름</strong>: 탭에 표시되는 텍스트(비워둘 경우 언어 설정에 따른 기본 이름 적용).</li><li><strong>활성화 스위치</strong>: 탭 바 표시 여부 제어. 패널에서 탭의 <strong>×</strong> 버튼을 눌러 숨긴 경우 여기서 다시 켤 수 있습니다.</li></ul></li></ul><p>선택한 워크스페이스는 우측의 <strong>소스</strong> 및 <strong>애플리케이션</strong> 탭에서 구성합니다.</p><h2 id="_3-소스-설정-sources" tabindex="-1">3. 소스 설정 (Sources) <a class="header-anchor" href="#_3-소스-설정-sources" aria-label="Permalink to &quot;3. 소스 설정 (Sources)&quot;">​</a></h2><p>각 소스는 워크스페이스 내의 독립된 폴더 그룹을 나타냅니다.</p><ul><li><strong>폴더 추가</strong>: 대상 디렉토리를 선택합니다.</li><li><strong>표시 모드 (Display Mode)</strong>: <ul><li><strong>최근 변경된 파일</strong> —— 메모리 인덱스에서 최근 수정된 파일을 밀리초 단위로 조회(최신순).</li><li><strong>모든 콘텐츠</strong> —— 전체 항목을 표시하며 수정 시간 내림차순 또는 이름순으로 정렬할 수 있음(고정 바로가기 바 형태로 활용하기 좋음).</li><li><strong>폴더만</strong> —— 디렉터리만 표시.</li><li><strong>파일만</strong> —— 파일만 표시.</li></ul></li><li><strong>하위 폴더 포함</strong>: 하위 디렉토리 파일을 재귀적으로 포함합니다.</li><li><strong>드롭된 파일 수락</strong>: 켜면 외부 파일, 폴더, 웹 이미지를 이 그룹으로 끌어다 놓아 복사할 수 있습니다(충돌 알림 및 실행 취소를 지원하는 Windows 표준 복사 사용).</li><li><strong>필터링 규칙</strong>: 와일드카드 또는 검색 구문의 <code>@</code> 필터로 표시할 확장자 제한(예: <code>*.mp4;*.mkv</code>, <code>*.lnk;:@doc;:@img</code>, <code>*.lnk;:@doc|img</code>).</li><li><strong>최대 항목 수 및 시간 제한</strong>: 최대 표시 개수(0은 무제한) 및 N분 내 수정된 파일만 표시하도록 제한.</li><li><strong>상세 목록 vs 썸네일 타일</strong>: 그룹별로 목록 뷰 또는 썸네일 그리드 뷰를 선택 가능(타일은 원본 비율을 유지하며 균등 확장).</li></ul><h2 id="_4-플러그인-동적-탭-plugin-tabs" tabindex="-1">4. 플러그인 동적 탭 (Plugin Tabs) <a class="header-anchor" href="#_4-플러그인-동적-탭-plugin-tabs" aria-label="Permalink to &quot;4. 플러그인 동적 탭 (Plugin Tabs)&quot;">​</a></h2><p>플러그인이 제공하는 동적 목록을 퀵 패널에 배치할 수 있습니다. CoreExtensions에는 5개의 기본 탭이 포함되어 있습니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">플러그인 탭</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>즐겨찾기</strong></td><td style="text-align:left;">별표로 등록된 항목(URL은 브라우저에서 실행).</td></tr><tr><td style="text-align:left;"><strong>기록</strong></td><td style="text-align:left;">Lertaro를 통해 실행된 최근 항목 및 프로그램.</td></tr><tr><td style="text-align:left;"><strong>Windows 기록</strong></td><td style="text-align:left;">Windows &quot;최근 사용한 파일&quot;을 실제 파일 경로로 해석.</td></tr><tr><td style="text-align:left;"><strong>최근 디렉토리</strong></td><td style="text-align:left;">탐색기나 대화상자에서 직전에 탐색했던 폴더 추적.</td></tr><tr><td style="text-align:left;"><strong>최근 파일</strong></td><td style="text-align:left;">설정된 폴더들의 최신 파일들을 인덱스를 통해 집계 표시.</td></tr></tbody></table><p>각 탭의 표시 여부와 목록/타일 뷰 형식을 개별 설정할 수 있습니다.</p><h2 id="_5-앱-연동-및-전용-블랙리스트" tabindex="-1">5. 앱 연동 및 전용 블랙리스트 <a class="header-anchor" href="#_5-앱-연동-및-전용-블랙리스트" aria-label="Permalink to &quot;5. 앱 연동 및 전용 블랙리스트&quot;">​</a></h2><ul><li><strong>애플리케이션 연동 (Applications)</strong>: 특정 프로세스 이름(예: <code>chrome.exe</code> 또는 <code>devenv.exe</code>)을 등록하면 해당 앱 위에서 퀵 패널을 호출했을 때 해당 워크스페이스가 자동 활성화됩니다.</li><li><strong>퀵 패널 전용 블랙리스트</strong>: 패널 표시를 차단할 프로세스를 등록합니다. 전역 블랙리스트에 <strong>추가</strong>되어 작동합니다.</li></ul><h2 id="_6-패널-조작-가이드" tabindex="-1">6. 패널 조작 가이드 <a class="header-anchor" href="#_6-패널-조작-가이드" aria-label="Permalink to &quot;6. 패널 조작 가이드&quot;">​</a></h2><ul><li><strong>실시간 퍼지 필터링</strong>: 우측 상단 검색창에서 fzf 퍼지 매칭 및 한어병음으로 작업 공간을 빠르게 필터링합니다. 필터는 <strong>이름만</strong> 대상으로 하고 목록 순서를 바꾸지는 않으며, 항목이 모두 걸러진 그룹은 사라지지만 그 탭은 남아 있습니다. <code>Escape</code>는 먼저 필터를 지우고, <strong>두 번째</strong> <code>Escape</code>에서만 패널이 닫힙니다.</li><li><strong>키보드 탐색</strong>: 방향키로 그룹을 넘나들며 탐색하고 <code>Enter</code>로 강조된 항목을 열면 패널은 열린 상태로 유지됩니다. 순서는 <strong>순환하지 않습니다</strong>: 처음과 마지막 항목이 뚜렷한 끝이고, 빈 그룹은 건너뛰며, 아직 아무것도 선택하지 않은 상태에서는 <code>↑</code>와 <code>↓</code> 모두 첫 항목으로 갑니다. 타일 뷰에서는 네 방향키가 눈에 보이는 격자를 따라 이동합니다: <code>←</code>/<code>→</code>는 읽기 순서를 따라 행 경계를 넘고, <code>↑</code>/<code>↓</code>는 열을 유지합니다.</li><li><strong>탭 전환</strong>: <code>Ctrl</code> + <code>1</code>–<code>9</code>로 각 탭 간 빠른 이동.</li><li><strong>QuickLook 미리보기 및 고정</strong>: <code>Alt+P</code>로 미리보기 패널 호출, <code>Ctrl+T</code>(또는 헤더의 고정 버튼)로 포커스를 잃어도 닫히지 않도록 고정.</li><li><strong>포커스가 도착하는 위치</strong>: 패널을 호출하면 필터 상자에 캐럿이 놓이고 첫 항목이 이미 선택된 상태이므로, 입력하면 즉시 좁혀집니다. 그 상자가 포커스를 갖고 있는 동안 플러그인 액션 단축키는 의도적으로 물러섭니다. 여기서 <code>Ctrl+A</code>와 <code>Ctrl+C</code>는 파일 조작이 아니라 텍스트 편집입니다.</li><li><strong>액션 플라이아웃</strong>: 우클릭 <strong>누르기</strong>가 아니라 <strong>뗄 때</strong> 메인 윈도우와 같은 액션 플라이아웃이 커서 기준으로 열리므로, 선택되지 않은 행을 우클릭하면 그 행에 대한 메뉴가 됩니다. 이후 플라이아웃이 <code>↑ ↓ ← →</code>, <code>Enter</code>, <code>Space</code>, <code>Escape</code>를 담당합니다. 키 처리기를 패널에 걸어 두기 때문에, 평소라면 패널을 닫았을 바깥 클릭도 액션 플라이아웃이 열려 있는 동안에는 무시됩니다.</li><li><strong>행에 대한 마우스 동작</strong>: 좌클릭 더블클릭은 실행하고, 우클릭 더블클릭은 플라이아웃만 다시 열 뿐 실행하지 않습니다. 휠클릭은 미리보기를 토글하며, 행에 마우스를 올리면 선택이 이동합니다.</li><li><strong>패널 이동</strong>: 포인터가 헤더에 다가갈 때 헤더에 드래그 영역이 나타나며, 그곳을 드래그하면 패널이 이동하고 드래그 중에 닫히지 않습니다(탐색기에서 끌어낸 항목이 패널 위에 떨어질 수 있는 이유가 이것입니다).</li><li><strong>바깥 클릭</strong>: 포커스가 떠난 지 약 200ms 뒤에 패널이 숨겨지며, 자신이 드래그 중이거나 고정되어 있거나, 액션 플라이아웃이 열려 있거나, 자기가 연 미리보기가 전경인 동안에는 숨겨지지 않습니다. 자기 미리보기를 클릭한 것은 바깥 클릭이 아닙니다.</li><li><strong>선택 편집</strong>: 그룹 안의 빈 공간을 클릭하면 <code>Ctrl</code>이나 <code>Shift</code>를 누르지 않는 한 <strong>모든</strong> 그룹의 선택이 한 번에 해제됩니다. 러버밴드 드래그는 자기 그룹 안에서만 선택하며 <code>Ctrl</code>을 누르면 추가 선택이 되고, 한 그룹에서 시작한 밴드가 다른 그룹까지 뻗지는 않습니다.</li><li><strong>파일 받아들이기</strong>: <strong>Lertaro 안에서 시작한</strong> 드래그는 결코 수락되지 않으므로, 중간에 멈춘 드래그가 엉뚱한 복사본으로 바뀌지 않습니다. 패널은 바깥 클릭으로 닫히기 때문에 탐색기에서 파일을 끌어다 놓는 것은 패널이 <strong>고정</strong>되어 있을 때만 동작합니다. 놓기 작업은 항상 복사이며 이동은 아닙니다.</li><li><strong>그룹 제목</strong>: 제목의 이름, 경로, 규칙 줄을 클릭하면 그룹이 접히고 다시 펴지며, 정렬과 보기는 옆에 별도 버튼으로 있습니다. 정렬, 보기 모드, 접힘 상태는 세션 단위이고, 탭 순서와 탭 닫기는 저장됩니다.</li></ul>',19)])])}const p=o(s,[["render",n]]);export{h as __pageData,p as default};
